const retained=[];
for(let round=0;round<12;round++){
 let batch=[];
 for(let i=0;i<20000;i++){
  const f=new Function('x','let a=x+1; let b=a*2; return b + '+(i%251)+';');
  batch.push(f);
  if(i%100===0)retained.push(f);
 }
 batch=null;
 Bun.gc(true);
}
let sum=0;
for(const f of retained)sum+=f(3);
console.log(retained.length,sum);
